/bin/zsh -lc "python3 -B - <<'PY'
import ledger

base = {\"currency\": \"USD\", \"members\": [\"alice\", \"bob\"], \"expenses\": []}
valid = {\"id\": \"expense\\\\42\", \"payer\": \"alice\", \"amount\": \"1\", \"split\": {\"type\": \"equal\"}}
values = [None, True, False, 42, 1.0, [], [None], {}, {\"bob\": None}, \"\", \"alice\"]

for field in valid:
    for value in values:
        expense = dict(valid, **{field: value})
        try:
            ledger.settle(dict(base, expenses=[expense]))
        except ledger.ValidationError as error:
            if isinstance(expense[\"id\"], str):
                assert expense[\"id\"] in str(error), error

assert ledger.balances(base) == {\"alice\": 0, \"bob\": 0}
assert ledger.settle(base) == []
print(\"Malformed expense values and empty ledgers checked through the public API\")
PY"

